# app/main.py
import os

from fastapi import FastAPI
from prometheus_fastapi_instrumentator import Instrumentator

app = FastAPI(title="zero-to-prod")
Instrumentator().instrument(app).expose(app, endpoint="/metrics")


@app.get("/")
def root():
    return {"message": os.environ.get("GREETING", "hello from zero-to-prod")}


@app.get("/health")
def health():
    return {"status": "ok"}

terraform {
  required_version = ">= 1.10"

  backend "s3" {
    bucket       = "tfstate-zero-to-prod-123456789012"
    key          = "ec2/terraform.tfstate"
    region       = "eu-west-1"
    encrypt      = true
    use_lockfile = true
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

provider "aws" {
  region = var.region
}

# infra/variables.tf
variable "region" {
  type    = string
  default = "eu-west-1"
}

variable "name" {
  type    = string
  default = "zero-to-prod"
}

variable "image" {
  description = "Container image to run, e.g. ghcr.io/you/zero-to-prod:latest"
  type        = string
}

variable "grafana_password" {
  type      = string
  sensitive = true
}

variable "my_ip" {
  description = "Your public IP in CIDR form; Grafana and Prometheus are only reachable from here"
  type        = string
}

# infra/main.tf
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

data "aws_ssm_parameter" "al2023" {
  name = "/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64"
}

resource "aws_security_group" "app" {
  name        = var.name
  description = "web in, admin UIs only from my IP"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = [var.my_ip]
  }
  ingress {
    from_port   = 9090
    to_port     = 9090
    protocol    = "tcp"
    cidr_blocks = [var.my_ip]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "instance" {
  name = "${var.name}-instance"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.instance.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "instance" {
  name = "${var.name}-instance"
  role = aws_iam_role.instance.name
}

resource "aws_instance" "app" {
  ami                    = data.aws_ssm_parameter.al2023.value
  instance_type          = "t3.micro"
  subnet_id              = data.aws_subnets.default.ids[0]
  vpc_security_group_ids = [aws_security_group.app.id]
  iam_instance_profile   = aws_iam_instance_profile.instance.name

  user_data = templatefile("${path.module}/user_data.sh", {
    image            = var.image
    grafana_password = var.grafana_password
  })
  user_data_replace_on_change = true

  root_block_device {
    volume_size = 16
  }

  tags = { Name = var.name }
}

resource "aws_eip" "app" {
  instance = aws_instance.app.id
  tags     = { Name = var.name }
}

# infra/outputs.tf
output "public_ip" {
  value = aws_eip.app.public_ip
}

output "urls" {
  value = {
    app        = "http://${aws_eip.app.public_ip}/"
    grafana    = "http://${aws_eip.app.public_ip}:3000/"
    prometheus = "http://${aws_eip.app.public_ip}:9090/"
  }
}

ACCOUNT=$(aws sts get-caller-identity --query Account --output text)
cat > trust.json <<EOF
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": {"Federated": "arn:aws:iam::$ACCOUNT:oidc-provider/token.actions.githubusercontent.com"},
    "Action": "sts:AssumeRoleWithWebIdentity",
    "Condition": {
      "StringEquals": {"token.actions.githubusercontent.com:aud": "sts.amazonaws.com"},
      "StringLike": {"token.actions.githubusercontent.com:sub": "repo:YOUR_GITHUB_USER/zero-to-prod:*"}
    }
  }]
}
EOF
aws iam create-role --role-name github-zero-to-prod --assume-role-policy-document file://trust.json
rm trust.json
